import json
from httpbin.core import app
client = app.test_client()

def test_put_json_body_reflected_in_json_field():
    payload = json.dumps({"key": "value"})
    r = client.put('/put', data=payload, content_type='application/json')
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['json'] == {"key": "value"}
    assert body['form'] == {}
    assert body['args'] == {}
    assert body['files'] == {}
    assert body['data'] == payload
    assert body['json']['key'] == 'value'

test_put_json_body_reflected_in_json_field()

from httpbin.core import app
client = app.test_client()

def test_put_with_query_args_reflected_in_args_field():
    r = client.put('/put?foo=bar')
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['args'] == {'foo': 'bar'}
    assert 'foo=bar' in body['url']
    assert body['form'] == {}
    assert body['json'] is None
    assert body['files'] == {}

test_put_with_query_args_reflected_in_args_field()
